<span class="line">p <span class="token operator">=</span> gio<span class="token punctuation">.</span>Geometry<span class="token punctuation">(</span>gtype<span class="token operator">=</span><span class="token string">&#39;Point&#39;</span><span class="token punctuation">)</span>       <span class="token comment"># an empty Point geometry</span></span>
