<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;original:&#39;</span><span class="token punctuation">,</span> g<span class="token punctuation">.</span>gtype<span class="token punctuation">,</span> <span class="token builtin">len</span><span class="token punctuation">(</span>g<span class="token punctuation">)</span><span class="token punctuation">,</span> g<span class="token punctuation">.</span>is_empty<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
