<span class="line">r <span class="token operator">=</span> g<span class="token punctuation">.</span>delaunay_triangulation<span class="token punctuation">(</span>tolerance<span class="token operator">=</span><span class="token number">0.01</span><span class="token punctuation">)</span></span>
