<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;After bytes :&#39;</span><span class="token punctuation">,</span> g<span class="token punctuation">.</span>wkb_size<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
